const sites=[{id:'lab',name:'BIG CRACK LAB',x:-11,z:-7,desc:'Research & upgrades'},{id:'rig',name:'MAIN DRILLING RIG',x:0,z:-2,desc:'Drilling control'},{id:'oil',name:'OIL DEPOT',x:11,z:-4,desc:'Fuel supply'},{id:'security',name:'SECURITY CONTROL',x:-10,z:6,desc:'Live camera feeds'}];
