function box(x,z,w,d,h,colors,label,options={}){
 const x0=x-w/2,x1=x+w/2,z0=z-d/2,z1=z+d/2;
 poly([[x0,0,z0],[x1,0,z0],[x1,h,z0],[x0,h,z0]],colors.front,options.stroke||'#34433b',.7);
 poly([[x1,0,z0],[x1,0,z1],[x1,h,z1],[x1,h,z0]],colors.side,options.stroke||'#34433b',.7);
 poly([[x0,h,z0],[x1,h,z0],[x1,h,z1],[x0,h,z1]],colors.roof,options.stroke||'#34433b',.7);
 // architectural trim and window bays on visible front face
 if(options.windows){for(let i=0;i<options.windows;i++){let wx=x0+w*(i+1)/(options.windows+1),wy=h*.62;poly([[wx-.32,wy-.27,z0-.015],[wx+.32,wy-.27,z0-.015],[wx+.32,wy+.28,z0-.015],[wx-.32,wy+.28,z0-.015]],options.glass||'#84aaa0','#d3d5bd',.65);line3([wx,wy-.25,z0-.025],[wx,wy+.25,z0-.025],'#d2d8c6',.55)}}
 if(label){const p=project(x,h*.81,z0-.02);ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle=options.sign||'#263732';ctx.fillRect(-w*project(0,0,0).s*.18,-9,w*project(0,0,0).s*.36,18);ctx.fillStyle=options.labelColor||'#e4edcf';ctx.font=`700 ${clamp(w*1.35,7,13)}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(label,0,0);ctx.restore()}
}
function drawGround(){
 let gradient=ctx.createLinearGradient(0,0,0,H);gradient.addColorStop(0,'#a4bd76');gradient.addColorStop(.55,'#91ad68');gradient.addColorStop(1,'#78945d');ctx.fillStyle=gradient;ctx.fillRect(0,0,W,H);
 // restrained grass grain
 for(let i=0;i<135;i++){let x=(i*173.7+31)%W,y=(i*91.3+55)%H;ctx.strokeStyle=i%3?'#d2d89a26':'#425d3c25';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+2+(i%4),y-2);ctx.stroke()}
 // paved campus roads connect every facility
 poly([[-20,0,-10],[18,0,-10],[18,0,-7],[-20,0,-7]],'#aeb2a5','#c6c6b7',1);
 poly([[-13,0,-12],[-10,0,-12],[-10,0,10],[-13,0,10]],'#b2b5a9','#c9c8b9',1);
 poly([[-2,0,-10],[1,0,-10],[1,0,8],[-2,0,8]],'#aaafa3','#c5c6b8',1);
 poly([[8,0,-10],[11,0,-10],[11,0,0],[8,0,0]],'#aaafa3','#c5c6b8',1);
 for(let x=-18;x<17;x+=2.5){poly([[x,0,-8.65],[x+1.15,0,-8.65],[x+1.15,0,-8.48],[x,0,-8.48]],'#e7dfb3aa')}
 // perimeter chain fence, broken for entry
 for(let x=-19;x<=19;x+=1.2){if(x>-2&&x<3)continue;line3([x,0,-13],[x,1.35,-13],'#66756b99',.7);line3([x,0,12],[x,1.35,12],'#66756b88',.7)}
 line3([-19,.7,-13],[19,.7,-13],'#66756b99',.8);line3([-19,1.25,-13],[19,1.25,-13],'#66756b88',.7);line3([-19,.7,12],[19,.7,12],'#66756b88',.8);
 for(let z=-12;z<=12;z+=1.2){line3([-19,0,z],[-19,1.3,z],'#66756b88',.7);line3([19,0,z],[19,1.3,z],'#66756b88',.7)}
 line3([-19,.7,-12],[ -19,.7,12],'#66756b88',.7);line3([19,.7,-12],[19,.7,12],'#66756b88',.7);
 // poles, lamps, warning panels
 for(const [x,z] of [[-17,-8],[6,-8],[14,2],[-16,7]])drawLamp(x,z);
 for(const [x,z] of [[-5,-9],[4,-9],[6,-6],[13,-1]])drawPole(x,z);
 drawWarning(-4,-7);drawContainer(14,3);drawContainer(15,3);
}
function drawLamp(x,z){line3([x,0,z],[x,3.8,z],'#3e5148',2);line3([x,3.8,z],[x+.48,4.05,z],'#3e5148',2);let p=project(x+.48,4,z);ctx.fillStyle='#ffedb9';ctx.shadowColor='#ffe6a5';ctx.shadowBlur=state.nightOut?0:10;ctx.beginPath();ctx.arc(p.x,p.y,3,0,7);ctx.fill();ctx.shadowBlur=0;if(isNight()&&!state.nightOut){ctx.beginPath();ctx.arc(p.x,p.y,21,0,7);ctx.fillStyle='#ffdf8a18';ctx.fill()}}
function drawPole(x,z){line3([x,0,z],[x,3.3,z],'#745d48',2);line3([x-.4,2.9,z],[x+.4,2.9,z],'#745d48',2);line3([x-.3,3,z-.13],[x-.3,3,z+.13],'#697d75',.9)}
function drawWarning(x,z){box(x,z,.55,.18,.75,{front:'#cf6a4b',side:'#9d5040',roof:'#e18c58'},null);textAt(x,.5,z-.11,'!',12,'#fff4d8')}
function drawContainer(x,z){box(x,z,1.7,.9,1.35,{front:'#597e76',side:'#466861',roof:'#77958a'},null,{stroke:'#435f57'});for(let i=0;i<5;i++)line3([x-.72+i*.36,.08,z-.46],[x-.72+i*.36,1.25,z-.46],'#a2b3a072',.6)}

function drawLab(){
 box(-11,-7,7.4,4.7,3.8,{front:'#b7bcb0',side:'#929f98',roof:'#4b625b'},'BIG CRACK LAB',{windows:5,sign:'#263a34',labelColor:'#d8f36a',glass:'#719790'});
 // second storey clerestory and roof plant
 box(-11,-7.2,5.9,3.25,1.35,{front:'#778b82',side:'#657b72',roof:'#556d64'},null,{windows:4,glass:'#a2c3b0'});
 box(-11,-7.3,1.1,.85,1.55,{front:'#718078',side:'#5d6e65',roof:'#87948a'},null);
 // entrance / auto glass door
 let open=state.door;const doorx=-11+open*.7;poly([[doorx-.55,0,-4.62],[doorx+.55,0,-4.62],[doorx+.55,2.1,-4.62],[doorx-.55,2.1,-4.62]],'#558177','#d9dfc9',1);line3([doorx,0,-4.6],[doorx,2.1,-4.6],'#d9dfc9',1);
 textAt(-11,4.15,-7,'RESEARCH • GEOLOGY • EXTRACTION',7,'#f5f0d7');
 box(-8.1,-4.8,1.7,.85,1.7,{front:'#687c70',side:'#50695f',roof:'#819087'},null);
 // exterior wall signplate glow
 let p=project(-11,3.1,-4.58);ctx.fillStyle='rgba(216,243,106,.17)';ctx.fillRect(p.x-49,p.y-4,98,8);
}
function drawOil(){
 box(11,-4,4.3,3.4,2.8,{front:'#739890',side:'#52716a',roof:'#395a53'},'OIL DEPOT',{windows:2,sign:'#23433d',glass:'#aed0b3'});
 // awning and fuel tanks
 box(11,-2.05,3.8,.7,.25,{front:'#d0ac68',side:'#b89251',roof:'#dfbd75'},null);
 for(let i=0;i<3;i++){let x=8.7+i*1.35;const p=project(x,1.05,-6.5);let r=15*project(0,0,-6.5).s/24;ctx.fillStyle=['#aeb5a3','#7c9a8b','#d0b673'][i];ctx.beginPath();ctx.ellipse(p.x,p.y,r,r*.75,0,0,7);ctx.fill();let p2=project(x,0,-6.5);ctx.fillRect(p2.x-r,p2.y-r*.5,r*2,r*1.4);ctx.beginPath();ctx.ellipse(p2.x,p2.y+r*.9,r,r*.43,0,0,7);ctx.fill()}
 textAt(11,3.15,-4,'FUEL · AUTHORIZED PERSONNEL',6,'#eff2da');
}
function drawSecurity(){
 box(-10,6,5.3,3.6,2.8,{front:'#8b9b8e',side:'#697d73',roof:'#465d54'},'SECURITY',{windows:3,sign:'#273c35',glass:'#566e69'});
 // exterior camera
 line3([-7.15,2.5,4.2],[-6.65,2.7,3.9],'#354940',2);box(-6.48,2.75,.48,.32,.28,{front:'#253d39',side:'#172d2a',roof:'#49635c'},null);
 textAt(-10,3.15,6,'PERIMETER MONITORING',7,'#f0f3db');
}
function drawRig(){
 // substantial concrete foundation pad
 poly([[-3,0,-4],[3.3,0,-4],[3.3,0,1.5],[-3,0,1.5]],'#777f72','#d0ccad',1);
 // legs and triangular lattice drilling tower
 const tower=[[-1.85,0,-2.8],[1.85,0,-2.8],[-1.28,7,-2.8],[1.28,7,-2.8]];
 poly([tower[0],tower[1],tower[3],tower[2]],'#667874','#435750',1);
 for(let i=0;i<=6;i++){let y=i*1.05,w=1.85-y*.08;line3([-w,y,-2.82],[w,y,-2.82],i%2?'#b9bba5':'#e2cb87',1.25);if(i<6){line3([-w,y,-2.82],[w-.1,y+1.05,-2.82],'#9da898',.85);line3([w,y,-2.82],[-w+.1,y+1.05,-2.82],'#89998c',.85)}}
 line3([-1.85,0,-2.8],[-1.28,7,-2.8],'#e1d6ae',2.2);line3([1.85,0,-2.8],[1.28,7,-2.8],'#e1d6ae',2.2);
 // cap and pulley
 poly([[-1.35,7,-3.15],[1.35,7,-3.15],[0,7.55,-3.15]],'#d2b45e','#514b38',1);line3([0,7,-2.8],[0,5.7,-2.8],'#e9dcaa',2.5);
 // central moving drill pipe
 let drilling=state.running&&state.oil>0;let spin=performance.now()/110;
 line3([0,5.65,-2.8],[0,Math.max(1.05,5.15-(drilling?(spin%1)*.65:0)),-2.8],'#c6c7ad',2.8);
 for(let i=0;i<4;i++){let ang=spin+i*Math.PI/2;let pp=project(Math.cos(ang)*.28,4.5+Math.sin(ang)*.28,-2.8);ctx.fillStyle='#e2b858';ctx.beginPath();ctx.arc(pp.x,pp.y,3,0,7);ctx.fill()}
 // lower drill cabinet / controls
 box(0,-.7,2.1,1.25,1.2,{front:'#3f685e',side:'#31534b',roof:'#718276'},null);
 poly([[-.65,1.2,-1.34],[.65,1.2,-1.34],[.65,1.75,-1.34],[-.65,1.75,-1.34]],'#253c39','#9aa389',.7);
 let screen=project(0,1.49,-1.35);ctx.fillStyle=drilling?'#a1bd68':'#506b59';ctx.fillRect(screen.x-11,screen.y-4,22,8);ctx.fillStyle='#d5e0ab';ctx.font='5px monospace';ctx.textAlign='center';ctx.fillText(drilling?'DRILL LIVE':'STANDBY',screen.x,screen.y+1);
 // depth sign board
 box(2.4,-1.9,1.1,.4,1.9,{front:'#425850',side:'#344840',roof:'#60776c'},null);textAt(2.4,1.25,-2.12,`${Math.floor(state.depth)} m`,8,'#d7ed9f');textAt(2.4,.85,-2.12,'DEPTH',6,'#d4d8c6');
 // rails/platforms
 for(let y of [2.4,4.4,6.35]){line3([-1.65,y,-2.7],[1.65,y,-2.7],'#d3c8a4',1.2);line3([-1.65,y,-2.7],[-1.65,y+.32,-2.7],'#d3c8a4',.8);line3([1.65,y,-2.7],[1.65,y+.32,-2.7],'#d3c8a4',.8)}
 // base hazard paint
 for(let i=0;i<8;i++){let x=-2.7+i*.72;poly([[x,0,-3.95],[x+.35,0,-3.95],[x+.68,0,-3.62],[x+.33,0,-3.62]],i%2?'#e7d291':'#353f35')}
 textAt(0,8.0,-2.8,'DEEP CORE · MK IV',9,'#f2e5ad');
 // borehole rim, metallic rings and depth shaft illusion
 circleAt(0,.02,-.6,1.45,'#52483b');circleAt(0,.025,-.6,1.15,'#2c3029');circleAt(0,.035,-.6,.72,'#111918');for(let i=0;i<3;i++)circleAt(0,.045+i*.006,-.6,1.35-i*.19,'#9b8a64');
 let bp=project(0,.12,-.6);if(drilling){ctx.save();ctx.translate(bp.x,bp.y);ctx.rotate(performance.now()/400);ctx.strokeStyle='#c9dc87';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,8,0,Math.PI*1.45);ctx.stroke();ctx.restore()}
 textAt(0,.1,1.8,'ACTIVE BOREHOLE',6,'#f2e5ad');
}
function drawRoadMark(){for(const [x,z,t] of [[-11,-3.9,'LAB'],[0,-4.8,'DRILL'],[11,-6.2,'FUEL']])textAt(x,.03,z,t,6,'#eee8c2aa')}
function drawPlayer(){
 const x=state.x,z=state.z;circleAt(x,.015,z,.38,'#26352e55');
 let bob=Math.sin(walk)*.045, body=project(x,.75+bob,z),head=project(x,1.47+bob,z),sc=body.s;
 // shadow / backpack, body, limbs
 line3([x-.12,.62+bob,z],[x-.2,.13+Math.abs(Math.sin(walk))*.12,z],'#38443c',Math.max(2,sc*.16));line3([x+.12,.62+bob,z],[x+.2,.13+Math.abs(Math.cos(walk))*.12,z],'#38443c',Math.max(2,sc*.16));
 line3([x-.24,1.03+bob,z],[x-.42,.62+bob,z],'#c5ad78',Math.max(2,sc*.15));line3([x+.24,1.03+bob,z],[x+.4,.68+bob,z],'#c5ad78',Math.max(2,sc*.15));
 ctx.fillStyle='#d19d59';ctx.beginPath();ctx.ellipse(body.x,body.y,sc*.28,sc*.38,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#668675';ctx.fillRect(body.x-sc*.23,body.y-sc*.12,sc*.46,sc*.36);ctx.fillStyle='#b9764d';ctx.beginPath();ctx.arc(head.x,head.y,Math.max(4,sc*.18),0,Math.PI*2);ctx.fill();ctx.fillStyle='#e6bb68';ctx.fillRect(head.x-sc*.23,head.y-sc*.07,sc*.46,sc*.12);
}
function drawSky(){let night=isNight(),g=ctx.createLinearGradient(0,0,0,H*.5);g.addColorStop(0,night?'#263944':'#90b8c2');g.addColorStop(.8,night?'#5c797a':'#d0d5aa');ctx.fillStyle=g;ctx.fillRect(0,0,W,H*.46);
 // distant soft flat horizon, no hills
 ctx.fillStyle=night?'#536b58':'#829c5e';ctx.fillRect(0,H*.39,W,H*.16);
 // atmosphere cloud strokes
 for(let i=0;i<5;i++){let x=((i*239+performance.now()*.003)%(W+160))-80,y=H*(.12+(i%3)*.07);ctx.fillStyle=night?'#dce8e817':'#f6f1dc38';ctx.beginPath();ctx.ellipse(x,y,40+i%2*20,5,0,0,7);ctx.fill()}
 if(night){for(let i=0;i<26;i++){let x=(i*137+34)%W,y=(i*41+8)%(H*.27);ctx.fillStyle='#fff4c9a8';ctx.fillRect(x,y,1.2,1.2)}let moon=ctx.createRadialGradient(W*.76,H*.12,2,W*.76,H*.12,40);moon.addColorStop(0,'#fff2c7');moon.addColorStop(1,'#fff2c700');ctx.fillStyle=moon;ctx.fillRect(W*.76-40,H*.12-40,80,80);ctx.fillStyle='#fff0c8';ctx.beginPath();ctx.arc(W*.76,H*.12,6,0,7);ctx.fill()}
 let sunX=W*(.76-.34*((state.day-.5)*2)),sunY=H*(.16+Math.abs(state.day-.5)*.24);ctx.fillStyle=night?'#e8c67d':'#fff0bd';ctx.globalAlpha=night?.3:.85;ctx.beginPath();ctx.arc(sunX,sunY,9,0,7);ctx.fill();ctx.globalAlpha=1;
}
function isNight(){return state.day<.23||state.day>.77}
function drawWorld(){drawSky();drawGround(); // object order via depth sorting for objects
 const objects=[[-11,-7,drawLab],[-10,6,drawSecurity],[0,-2,drawRig],[11,-4,drawOil]];objects.sort((a,b)=>{let pa=project(a[0],0,a[1]),pb=project(b[0],0,b[1]);return pa.y-pb.y});objects.forEach(o=>o[2]());drawRoadMark();drawPlayer();if(state.nightOut&&isNight())drawThreat();if(isNight()){ctx.fillStyle='rgba(17,30,42,.16)';ctx.fillRect(0,0,W,H)} }
function drawThreat(){let x=13,z=-10,p=project(x,0,z),s=p.s;ctx.fillStyle='#11191a';ctx.beginPath();ctx.ellipse(p.x,p.y-s*.8,s*.22,s*.58,0,0,7);ctx.fill();ctx.beginPath();ctx.arc(p.x,p.y-s*1.35,s*.19,0,7);ctx.fill();ctx.fillStyle='#e7e9ad';ctx.fillRect(p.x-s*.1,p.y-s*1.41,2,2);ctx.fillRect(p.x+s*.055,p.y-s*1.41,2,2)}

function closestSite(){let best=null,dist=1e9;for(const s of sites){let d=Math.hypot(s.x-state.x,s.z-state.z);if(d<dist){best=s;dist=d}}return{site:best,dist}}
function setToast(text,warn=false){$('toast-text').textContent=text;$('toast').classList.toggle('warn',warn);$('toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('toast').classList.remove('show'),2800)}
function approach(){const {site,dist}=closestSite(),el=$('interaction');if(dist<3.2){el.classList.add('visible');$('interact-key').textContent=isTouch()?'TAP':'E';$('interact-title').textContent=site.id==='rig'?(state.running?'STOP DRILL':'START DRILL'):site.id==='oil'?'REFILL OIL':site.id==='security'?'VIEW CAMERAS':'ENTER LAB';$('interact-sub').textContent=site.desc;return site}el.classList.remove('visible');return null}
function isTouch(){return matchMedia('(pointer:coarse)').matches||W<760}
function interact(){if(state.modal)return;const s=approach();if(!s){setToast('Move closer to a facility to interact.');return}if(s.id==='lab')openLab();if(s.id==='rig')toggleRig();if(s.id==='oil')openOil();if(s.id==='security')openSecurity()}
function toggleRig(){if(state.running){state.running=false;setToast('Drilling paused. Core depth secured.');return}if(state.oil<=0){setToast('OUT OF OIL — visit the Oil Depot to refuel.',true);return}state.running=true;setToast('Drill online. Core extraction in progress.');if(!state.guideSeen){state.guideSeen=true;setTimeout(()=>{if(!state.modal)openGuide()},900)}}
function openModal(html){$('modal-content').innerHTML=html;$('modal-backdrop').classList.add('open');state.modal='open'}function closeModal(){$('modal-backdrop').classList.remove('open');state.modal='';$('modal-content').innerHTML=''}
const upgradeData=[['power','Drill power','Drive deeper into hard rock. Each level boosts core yield.','↧'],['speed','Drilling speed','Increase the rate of your drilling progress.','⟳'],['durability','Machine durability','Reinforce the rig against wear during operation.','⬡'],['multiplier','Money multiplier','Improve income from each core sample.','＄'],['efficiency','Oil efficiency','Make each tank last longer while drilling.','◉']];
function labHTML(){return `<div class="modal-kicker">BIG CRACK LAB / RESEARCH DIVISION</div><h2>Equipment upgrades</h2><p class="modal-intro">Research the next generation of deep-core extraction equipment. Upgrades are permanent and take effect immediately.</p><div class="upgrade-grid">${upgradeData.map(([key,name,desc,icon])=>{let level=state.upgrades[key],cost=price[key]*Math.pow(level+1,1.55)|0;return `<article class="upgrade-card"><span class="upgrade-level">LVL ${level} / 8</span><div class="upgrade-icon">${icon}</div><h3>${name}</h3><p>${desc}</p><button class="buy-button" data-upgrade="${key}" ${level>=8||state.money<cost?'disabled':''}><span>${level>=8?'MAX LEVEL':'RESEARCH UPGRADE'}</span><b>${level>=8?'✓':'$'+cost}</b></button></article>`}).join('')}</div>`}
function openLab(){openModal(labHTML());$('modal-content').querySelectorAll('[data-upgrade]').forEach(btn=>btn.onclick=()=>buyUpgrade(btn.dataset.upgrade))}
function buyUpgrade(key){let level=state.upgrades[key],cost=price[key]*Math.pow(level+1,1.55)|0;if(level>=8)return;if(state.money<cost){setToast('Not enough funds for that upgrade.',true);return}state.money-=cost;state.upgrades[key]++;if(key==='durability')state.condition=Math.min(100,state.condition+15);renderHUD();setToast(`${upgradeData.find(x=>x[0]===key)[1]} upgraded to level ${level+1}.`);openLab()}
const oils=[['Basic','Reliable starter blend',80,60,'1×'],['Improved','Cleaner burn · less wear',180,95,'1.6×'],['Advanced','High-pressure formula',380,155,'2.6×'],['Premium','Deep-core synthetic',720,250,'4.2×']];
function oilHTML(){return `<div class="modal-kicker">FIELD SUPPLY / FUEL DEPOT</div><h2>Oil & supplies</h2><p class="modal-intro">The rig burns oil while it drills. One tank runs for 60 seconds before oil-efficiency upgrades.</p><div class="oil-options">${oils.map(([name,desc,cost,seconds,yieldv])=>`<article class="oil-option"><div class="drop">◉</div><h3>${name} oil</h3><p>${seconds}s capacity · ${yieldv} yield</p><p style="margin-top:5px">${desc}</p><button data-oil="${name}" ${state.money<cost?'disabled':''}>BUY · $${cost}</button></article>`).join('')}</div><p style="font:9px var(--mono);color:#829083;margin:15px 0 0">CURRENT TANK: ${state.oilType.toUpperCase()} · ${Math.ceil(state.oil)}s REMAINING</p>`}
function openOil(){openModal(oilHTML());$('modal-content').querySelectorAll('[data-oil]').forEach(btn=>btn.onclick=()=>buyOil(btn.dataset.oil))}
function buyOil(name){const o=oils.find(x=>x[0]===name);if(state.money<o[2]){setToast('Not enough funds for this fuel.',true);return}state.money-=o[2];state.oilMax=Math.round(o[3]*(1+state.upgrades.efficiency*.12));state.oil=state.oilMax;state.oilType=name;if(state.running)state.running=false;renderHUD();setToast(`${name} oil tank delivered. Rig ready when you are.`);openOil()}
function openSecurity(){state.feed=0;openModal(`<div class="modal-kicker">FIELD SECURITY / CCTV NETWORK</div><h2>Perimeter monitors</h2><p class="modal-intro">Six live feeds are available across the research site. Camera network: <b style="color:#65824e">● CONNECTED</b></p><div class="monitor-layout"><div class="feed-screen"><canvas id="feed-canvas"></canvas><div class="feed-overlay"><span id="feed-name">CAM 01 · MAIN ENTRANCE</span><span id="feed-time">--:--:--</span><span>REC ● &nbsp; SIGNAL 98%</span></div></div><div class="feed-list">${feeds.map((f,i)=>`<button class="feed-choice ${i===0?'active':''}" data-feed="${i}">CAM 0${i+1} · ${f.name}<small>● LIVE / 1080p</small></button>`).join('')}</div></div>`);document.querySelectorAll('[data-feed]').forEach(b=>b.onclick=()=>{state.feed=+b.dataset.feed;document.querySelectorAll('.feed-choice').forEach(x=>x.classList.toggle('active',x===b));$('feed-name').textContent=`CAM 0${state.feed+1} · ${feeds[state.feed].name.toUpperCase()}`;drawFeed()});drawFeed();updateFeedTime()}
function drawFeed(){const c=$('feed-canvas');if(!c)return;let r=c.getBoundingClientRect();c.width=r.width*devicePixelRatio;c.height=r.height*devicePixelRatio;let g=c.getContext('2d');g.scale(devicePixelRatio,devicePixelRatio);let w=r.width,h=r.height,feed=state.feed;g.fillStyle='#192623';g.fillRect(0,0,w,h);g.fillStyle='#526c58';g.fillRect(0,h*.53,w,h*.47);g.fillStyle='#a5af9360';g.fillRect(w*.08,h*.61,w*.84,h*.12);g.fillStyle='#d3d7ae';g.fillRect(w*.2,h*.64,w*.6,h*.018);
 if(feed===4){g.fillStyle='#485047';g.fillRect(w*.4,h*.1,w*.2,h*.9);g.fillStyle='#111716';g.fillRect(w*.445,h*.1,w*.11,h*.9);for(let i=0;i<8;i++){g.strokeStyle=`rgba(190,205,158,${.8-i*.07})`;g.beginPath();g.ellipse(w*.5,h*(.22+i*.1),w*(.04+i*.013),h*.03,0,0,7);g.stroke()}g.fillStyle='#bed28d';g.font='10px monospace';g.fillText(`DEPTH ${Math.floor(state.depth)} M`,10,20);g.fillText('BORE CAM / 4.8 KM',10,35)}else{
 // camera stylized live site view
 g.fillStyle='#344940';g.fillRect(w*.17,h*.3,w*.28,h*.3);g.fillStyle='#76867a';g.fillRect(w*.17,h*.27,w*.28,h*.07);g.fillStyle='#384e46';g.beginPath();g.moveTo(w*.14,h*.3);g.lineTo(w*.31,h*.16);g.lineTo(w*.48,h*.3);g.fill();g.fillStyle='#a5c0a3';for(let i=0;i<4;i++)g.fillRect(w*(.21+i*.055),h*.36,w*.027,h*.08);
 if(feed===1){g.strokeStyle='#d2bc75';g.lineWidth=4;g.beginPath();g.moveTo(w*.72,h*.25);g.lineTo(w*.68,h*.8);g.lineTo(w*.8,h*.25);g.stroke();g.fillStyle='#b49b5c';g.fillRect(w*.66,h*.78,w*.2,h*.05)}if(feed===3){g.fillStyle='#75a092';g.fillRect(w*.58,h*.48,w*.22,h*.2);g.fillStyle='#e2c47a';g.fillRect(w*.58,h*.45,w*.22,h*.04)}if(feed===5){g.strokeStyle='#798a79';for(let x=0;x<w;x+=12){g.beginPath();g.moveTo(x,h*.48);g.lineTo(x,h*.36);g.stroke()}g.fillStyle='#171d1b';g.beginPath();g.ellipse(w*.77,h*.48,6,14,0,0,7);g.fill()} }
 g.fillStyle='#e0edce';g.font='8px monospace';g.fillText('● REC',w-44,16);g.strokeStyle='#d8f36a30';g.lineWidth=1;g.strokeRect(4,4,w-8,h-8);g.fillStyle='#d8f36a';for(let i=0;i<4;i++){let x=i%2?w-12:8,y=i>1?h-12:8;g.fillRect(x,y,4,4)}
}
