 let min=Math.floor(state.day*24*60),hh=String(Math.floor(min/60)).padStart(2,'0'),mm=String(min%60).padStart(2,'0');$('clock').textContent=`${hh}:${mm}`;$('weather-name').textContent=isNight()?'NIGHT WATCH':'CLEAR SKIES';$('weather-icon').textContent=isNight()?'☾':'☀';$('weather-icon').style.color=isNight()?'#9cb8dc':'#d4a84e';
 const near=closestSite();let label=near.dist<6?near.site.name+' · '+near.site.desc.toUpperCase():'FIELD CAMP · OUTER YARD';$('site-name').textContent=label;let mp=$('map-player');mp.style.left=`${clamp(50+state.x*2.7,3,95)}%`;mp.style.top=`${clamp(53+state.z*2.5,3,95)}%`;
