}

function update(dt,now){state.day=(state.day+dt/180)%1;if(state.running){if(state.oil>0){state.oil-=dt;if(state.oil<=0){state.oil=0;state.running=false;setToast('OUT OF OIL — drilling has stopped. Visit the Oil Depot.',true)}else{let speed=1+state.upgrades.speed*.32,power=1+state.upgrades.power*.22;state.depth+=dt*3.1*speed*power;state.progress+=dt*3.8*speed;state.condition-=dt*(.055/(1+state.upgrades.durability*.3));if(state.progress>=100){state.progress-=100;let gain=Math.round((45+state.upgrades.power*13)*(1+state.upgrades.multiplier*.25));state.money+=gain;state.depth+=18;setToast(`Core sample recovered · +$${gain}`)}if(state.condition<=0){state.condition=0;state.running=false;setToast('MACHINE DAMAGE — repair required at the lab.',true)}}}
 }
 if(now-state.lastPay>=5000){let ticks=Math.floor((now-state.lastPay)/5000);state.lastPay+=ticks*5000;state.money+=ticks*(5+state.upgrades.multiplier*2)}
 if(isNight()&&!state.nightOut&&Math.random()<dt*.0014){state.nightOut=true;state.outageUntil=now+18000;state.running=false;setToast('GRID FAILURE · perimeter power lost. Check the security room.',true)}if(state.nightOut&&now>state.outageUntil){state.nightOut=false;setToast('Grid restored. Sector 04 is back online.')}
 let inputX=state.moveX,inputZ=state.moveZ;if(!isTouch()){inputX+=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);inputZ+=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)}let mag=Math.hypot(inputX,inputZ);if(mag>1){inputX/=mag;inputZ/=mag}if(mag>.01){let speed=dt*.0068;let c=Math.cos(state.yaw),s=Math.sin(state.yaw);state.x+=((inputX*c)+(inputZ*s))*speed;state.z+=((-inputX*s)+(inputZ*c))*speed;state.x=clamp(state.x,-18.5,18.5);state.z=clamp(state.z,-11.5,11.5);walk+=dt*.012*mag}
 approach();renderHUD()}
