const keys={};addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if(e.key.toLowerCase()==='e'||e.key===' '){if(state.modal)closeModal();else interact()}if(e.key==='Escape')closeModal()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse')pointer={x:e.clientX,y:e.clientY};else {pointer={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)}});canvas.addEventListener('pointermove',e=>{if(pointer){let dx=e.clientX-pointer.x;state.yaw+=dx*.0045;pointer={x:e.clientX,y:e.clientY}}});canvas.addEventListener('pointerup',()=>pointer=null);canvas.addEventListener('pointercancel',()=>pointer=null);canvas.addEventListener('wheel',e=>{state.zoom=clamp(state.zoom-e.deltaY*.0004,.78,1.35)},{passive:true});
$('touch-interact').addEventListener('click',interact);$('touch-camera').addEventListener('pointerdown',e=>{e.preventDefault();state.yaw+=Math.PI/4});$('sound-btn').addEventListener('click',()=>setToast('Radio channel tuned to facility dispatch.'));
const joy=$('joystick'),knob=$('joy-knob');let joyPointer=null;function joyMove(e){let r=joy.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=32,m=Math.hypot(dx,dy);if(m>max){dx*=max/m;dy*=max/m}knob.style.transform=`translate(${dx}px,${dy}px)`;state.moveX=dx/max;state.moveZ=dy/max}joy.addEventListener('pointerdown',e=>{e.preventDefault();joyPointer=e.pointerId;joy.setPointerCapture(e.pointerId);joyMove(e)});joy.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)joyMove(e)});function joyEnd(){joyPointer=null;state.moveX=0;state.moveZ=0;knob.style.transform=''}joy.addEventListener('pointerup',joyEnd);joy.addEventListener('pointercancel',joyEnd);
$('modal-close').onclick=closeModal;$('modal-backdrop').addEventListener('click',e=>{if(e.target===$('modal-backdrop'))closeModal()});$('help-btn').onclick=openGuide;addEventListener('orientationchange',()=>setTimeout(resize,150));
renderHUD();requestAnimationFrame(frame);
})();

