(()=>{'use strict';
const $=id=>document.getElementById(id),canvas=$('world'),ctx=canvas.getContext('2d');
const G={x:-1,z:7,yaw:0,zoom:1,money:420,oil:60,oilMax:60,oilType:'Basic',running:false,depth:0,condition:100,progress:0,lastPay:performance.now(),day:.61,nightOut:false,outageUntil:0,up:{power:0,speed:0,durability:0,multiplier:0,efficiency:0},modal:false,feed:0,moveX:0,moveZ:0,door:0};
let W=innerWidth,H=innerHeight,DPR=1,walk=0,last=performance.now(),toastTimer;const keys={};
const sites=[{id:'lab',name:'BIG CRACK LAB',x:-11,z:-7,desc:'Research & upgrades'},{id:'rig',name:'MAIN DRILLING RIG',x:0,z:-2,desc:'Drilling control'},{id:'oil',name:'OIL DEPOT',x:11,z:-4,desc:'Fuel supply'},{id:'security',name:'SECURITY CONTROL',x:-10,z:6,desc:'Live camera feeds'}];
const feeds=['Main Entrance','Mining Rig','BIG CRACK LAB','Oil Station','Borehole · 4,820 m','Outer Perimeter'];
const upgrades=[['power','Drill power','Drive deeper into hard rock. Each level boosts core yield.','↧',180],['speed','Drilling speed','Increase the rate of your drilling progress.','⟳',220],['durability','Machine durability','Reinforce the rig against wear during operation.','⬡',160],['multiplier','Money multiplier','Improve income from each core sample.','＄',250],['efficiency','Oil efficiency','Make each tank last longer while drilling.','◉',200]];
const oils=[['Basic','Reliable starter blend',80,60,'1×'],['Improved','Cleaner burn · less wear',180,95,'1.6×'],['Advanced','High-pressure formula',380,155,'2.6×'],['Premium','Deep-core synthetic',720,250,'4.2×']];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), night=()=>G.day<.23||G.day>.77;
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
function P(x,y=0,z){let dx=x-G.x,dz=z-G.z,a=G.yaw,rx=dx*Math.cos(a)-dz*Math.sin(a),rz=dx*Math.sin(a)+dz*Math.cos(a),s=Math.min(W/43,H/25)*G.zoom;return{x:W*.5+(rx-rz)*s*.70,y:H*.53+(rx+rz)*s*.30-y*s*.88,s}}
function poly(v,fill,stroke='#34433b',lw=.8){ctx.beginPath();v.forEach((a,i)=>{let p=P(...a);i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y)});ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke()}}
function line(a,b,color='#65736b',width=1){let p=P(...a),q=P(...b);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.stroke()}
function label(x,y,z,t,size=9,color='#f2edcf'){let p=P(x,y,z);ctx.font=`600 ${size}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='rgba(20,30,22,.45)';ctx.fillText(t,p.x+1,p.y+2);ctx.fillStyle=color;ctx.fillText(t,p.x,p.y)}
function box(x,z,w,d,h,c,name='',opts={}){let x0=x-w/2,x1=x+w/2,z0=z-d/2,z1=z+d/2;poly([[x0,0,z0],[x1,0,z0],[x1,h,z0],[x0,h,z0]],c.front);poly([[x1,0,z0],[x1,0,z1],[x1,h,z1],[x1,h,z0]],c.side);poly([[x0,h,z0],[x1,h,z0],[x1,h,z1],[x0,h,z1]],c.roof);
 if(opts.windows)for(let i=0;i<opts.windows;i++){let wx=x0+w*(i+1)/(opts.windows+1),wy=h*.62;poly([[wx-.32,wy-.27,z0-.015],[wx+.32,wy-.27,z0-.015],[wx+.32,wy+.28,z0-.015],[wx-.32,wy+.28,z0-.015]],opts.glass||'#84aaa0','#d3d5bd',.5)}
 if(name){let p=P(x,h*.81,z0-.03),s=clamp(w*1.35,7,13);ctx.fillStyle=opts.sign||'#263732';ctx.fillRect(p.x-w*p.s*.13,p.y-8,w*p.s*.26,16);ctx.fillStyle=opts.labelColor||'#e4edcf';ctx.font=`700 ${s}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(name,p.x,p.y)}}
function ellipse(x,y,z,r,color){let p=P(x,y,z);ctx.beginPath();ctx.ellipse(p.x,p.y,r*p.s,r*p.s*.56,0,0,7);ctx.fillStyle=color;ctx.fill()}
function sky(){let g=ctx.createLinearGradient(0,0,0,H*.5);g.addColorStop(0,night()?'#263944':'#90b8c2');g.addColorStop(.8,night()?'#5c797a':'#d0d5aa');ctx.fillStyle=g;ctx.fillRect(0,0,W,H*.5);ctx.fillStyle=night()?'#536b58':'#829c5e';ctx.fillRect(0,H*.39,W,H*.16);for(let i=0;i<5;i++){let x=(i*239+performance.now()*.003)%(W+120)-60,y=H*(.12+(i%3)*.07);ctx.fillStyle=night()?'#dce8e817':'#f6f1dc38';ctx.beginPath();ctx.ellipse(x,y,45,5,0,0,7);ctx.fill()}if(night()){for(let i=0;i<25;i++){ctx.fillStyle='#fff4c9a8';ctx.fillRect((i*137+34)%W,(i*41+8)%(H*.27),1,1)}ctx.fillStyle='#fff0c8';ctx.beginPath();ctx.arc(W*.76,H*.12,6,0,7);ctx.fill()}else{ctx.fillStyle='#fff0bd';ctx.beginPath();ctx.arc(W*.7,H*.16,9,0,7);ctx.fill()}}
