function nearest(){let best,dist=1e9;sites.forEach(s=>{let d=Math.hypot(s.x-G.x,s.z-G.z);if(d<dist){best=s;dist=d}});return{site:best,dist}}
function toast(msg,warn=false){$('toast-text').textContent=msg;$('toast').classList.toggle('warn',warn);$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2800)}
function touch(){return matchMedia('(pointer:coarse)').matches||W<760}
function approach(){let {site,dist}=nearest(),el=$('interaction');if(dist<3.2){el.classList.add('visible');$('interact-key').textContent=touch()?'TAP':'E';$('interact-title').textContent=site.id==='rig'?(G.running?'STOP DRILL':'START DRILL'):site.id==='oil'?'REFILL OIL':site.id==='security'?'VIEW CAMERAS':'ENTER LAB';$('interact-sub').textContent=site.desc;return site}el.classList.remove('visible');return null}
function interact(){if(G.modal)return;let s=approach();if(!s){toast('Move closer to a facility to interact.');return}if(s.id==='lab')openLab();if(s.id==='rig')toggleRig();if(s.id==='oil')openOil();if(s.id==='security')openSecurity()}
function toggleRig(){if(G.running){G.running=false;toast('Drilling paused. Core depth secured.');return}if(G.oil<=0){toast('OUT OF OIL — visit the Oil Depot to refuel.',true);return}G.running=true;toast('Drill online. Core extraction in progress.');if(!G.seen){G.seen=true;setTimeout(()=>{if(!G.modal)openGuide()},900)}}
function modal(html){$('modal-content').innerHTML=html;$('modal-backdrop').classList.add('open');G.modal=true}function close(){G.modal=false;$('modal-backdrop').classList.remove('open');$('modal-content').innerHTML=''}
function openLab(){modal(`<div class="modal-kicker">BIG CRACK LAB / RESEARCH DIVISION</div><h2>Equipment upgrades</h2><p class="modal-intro">Research the next generation of deep-core extraction equipment. Upgrades are permanent and take effect immediately.</p><div class="upgrade-grid">${upgrades.map(([key,name,desc,icon,base])=>{let lv=G.up[key],cost=base*Math.pow(lv+1,1.55)|0;return `<article class="upgrade-card"><span class="upgrade-level">LVL ${lv} / 8</span><div class="upgrade-icon">${icon}</div><h3>${name}</h3><p>${desc}</p><button class="buy-button" data-up="${key}" ${lv>=8||G.money<cost?'disabled':''}><span>${lv>=8?'MAX LEVEL':'RESEARCH UPGRADE'}</span><b>${lv>=8?'✓':'$'+cost}</b></button></article>`}).join('')}</div>`);document.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>buyUpgrade(b.dataset.up))}
function buyUpgrade(k){let u=upgrades.find(a=>a[0]===k),lv=G.up[k],cost=u[4]*Math.pow(lv+1,1.55)|0;if(lv>=8)return;if(G.money<cost){toast('Not enough funds for that upgrade.',true);return}G.money-=cost;G.up[k]++;if(k==='durability')G.condition=Math.min(100,G.condition+15);hud();toast(`${u[1]} upgraded to level ${lv+1}.`);openLab()}

