 function rig(){poly([[-3,0,-4],[3.3,0,-4],[3.3,0,1.5],[-3,0,1.5]],'#777f72','#d0ccad');poly([[-1.85,0,-2.8],[1.85,0,-2.8],[1.28,7,-2.8],[-1.28,7,-2.8]],'#667874','#435750');for(let i=0;i<=6;i++){let y=i*1.05,w=1.85-y*.08;line([-w,y,-2.82],[w,y,-2.82],i%2?'#b9bba5':'#e2cb87',1.25);if(i<6){line([-w,y,-2.82],[w-.1,y+1.05,-2.82],'#9da898');line([w,y,-2.82],[-w+.1,y+1.05,-2.82],'#89998c')}}line([-1.85,0,-2.8],[-1.28,7,-2.8],'#e1d6ae',2.2);line([1.85,0,-2.8],[1.28,7,-2.8],'#e1d6ae',2.2);poly([[-1.35,7,-3.15],[1.35,7,-3.15],[0,7.55,-3.15]],'#d2b45e');let drilling=G.running&&G.oil>0,spin=performance.now()/110;line([0,5.65,-2.8],[0,drilling?5.15-(spin%1)*.65:5.15,-2.8],'#c6c7ad',2.8);for(let i=0;i<4;i++){let a=spin+i*Math.PI/2,p=P(Math.cos(a)*.28,4.5+Math.sin(a)*.28,-2.8);ctx.fillStyle='#e2b858';ctx.beginPath();ctx.arc(p.x,p.y,3,0,7);ctx.fill()}box(0,-.7,2.1,1.25,1.2,{front:'#3f685e',side:'#31534b',roof:'#718276'});poly([[-.65,1.2,-1.34],[.65,1.2,-1.34],[.65,1.75,-1.34],[-.65,1.75,-1.34]],'#253c39','#9aa389');let sc=P(0,1.49,-1.35);ctx.fillStyle=drilling?'#a1bd68':'#506b59';ctx.fillRect(sc.x-11,sc.y-4,22,8);ctx.fillStyle='#d5e0ab';ctx.font='5px monospace';ctx.textAlign='center';ctx.fillText(drilling?'DRILL LIVE':'STANDBY',sc.x,sc.y+1);box(2.4,-1.9,1.1,.4,1.9,{front:'#425850',side:'#344840',roof:'#60776c'});label(2.4,1.25,-2.12,`${Math.floor(G.depth)} m`,8,'#d7ed9f');label(2.4,.85,-2.12,'DEPTH',6);for(let y of [2.4,4.4,6.35])line([-1.65,y,-2.7],[1.65,y,-2.7],'#d3c8a4',1.2);for(let i=0;i<8;i++){let x=-2.7+i*.72;poly([[x,0,-3.95],[x+.35,0,-3.95],[x+.68,0,-3.62],[x+.33,0,-3.62]],i%2?'#e7d291':'#353f35',null)}label(0,8,-2.8,'DEEP CORE · MK IV',9,'#f2e5ad');ellipse(0,.02,-.6,1.45,'#52483b');ellipse(0,.025,-.6,1.15,'#2c3029');ellipse(0,.035,-.6,.72,'#111918');for(let i=0;i<3;i++)ellipse(0,.045+i*.006,-.6,1.35-i*.19,'#9b8a64');if(drilling){let p=P(0,.12,-.6);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(performance.now()/400);ctx.strokeStyle='#c9dc87';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,8,0,Math.PI*1.45);ctx.stroke();ctx.restore()}label(0,.1,1.8,'ACTIVE BOREHOLE',6,'#f2e5ad')}
