function buyUpgrade(k){let u=upgrades.find(a=>a[0]===k),lv=G.up[k],cost=u[4]*Math.pow(lv+1,1.55)|0;if(lv>=8)return;if(G.money<cost){toast('Not enough funds for that upgrade.',true);return}G.money-=cost;G.up[k]++;if(k==='durability')G.condition=Math.min(100,G.condition+15);hud();toast(`${u[1]} upgraded to level ${lv+1}.`);openLab()}

function openOil(){const packs=[['FIELD CANISTER',30,55],['SHIFT DRUM',75,110],['RESERVOIR TANK',180,230],['EMERGENCY RESERVE',360,410]];modal(`<div class="modal-kicker">OIL DEPOT / SUPPLY OFFICE</div><h2>Refuel the operation</h2><p class="modal-intro">Fuel is consumed only while the rig is running. A larger purchase gives the crew more time in the field.</p><div class="oil-options">${packs.map(([name,amount,cost],i)=>`<article class="oil-option"><span class="drop">◉</span><h3>${name}</h3><p>+${amount} SEC · $${cost}</p><button data-fuel="${i}" ${G.money<cost?'disabled':''}>PURCHASE</button></article>`).join('')}</div><p class="modal-intro" style="margin:16px 0 0">Fuel remaining: <b>${formatTime(G.oil)}</b> · Current funds: <b>$${Math.floor(G.money)}</b></p>`);document.querySelectorAll('[data-fuel]').forEach(b=>b.onclick=()=>buyFuel(Number(b.dataset.fuel)))}
function buyFuel(i){const packs=[[30,55],[75,110],[180,230],[360,410]], [amount,cost]=packs[i];if(G.money<cost){toast('Insufficient funds for that fuel order.',true);return}G.money-=cost;G.oil+=amount;G.oilMax=Math.max(G.oilMax,G.oil);hud();toast(`${amount} seconds of drill fuel delivered.`);openOil()}
function openSecurity(){const cams=[['NORTH GATE','Gate 01'],['DRILL FLOOR','Rig 02'],['RESEARCH WING','Lab 03'],['OIL DEPOT','Depot 04'],['SOUTH FENCE','Perimeter 05'],['YARD OVERVIEW','Sector 06']];modal(`<div class="modal-kicker">SECURITY / CLOSED-CIRCUIT MONITORING</div><h2>Perimeter cameras</h2><p class="modal-intro">Six live feeds are routed to this station. Night outages can interrupt perimeter coverage.</p><div class="camera-grid">${cams.map(([name,id],i)=>`<button class="camera-tile" data-cam="${i}"><div class="camera-feed feed-${i}"><span class="feed-label">CAM 0${i+1} · ${night()?'NIGHT':'DAY'}</span><i class="feed-cross"></i><b>${G.nightOut&&i!==1?'SIGNAL LOST':'● REC'}</b><span class="feed-location">${name}</span></div><small>${id}</small></button>`).join('')}</div><p id="camera-status" class="modal-intro camera-status">${G.nightOut?'WARNING: PERIMETER POWER INTERRUPTION DETECTED.':'All six feeds nominal · Last sweep 00:04 ago'}</p>`);document.querySelectorAll('[data-cam]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.camera-tile').forEach(t=>t.classList.remove('selected'));b.classList.add('selected');$('camera-status').textContent=`CAMERA 0${Number(b.dataset.cam)+1} selected · ${G.nightOut?'Backup power active':'Signal nominal'} · Recording`})}
function openGuide(){modal(`<div class="modal-kicker">BIG CRACK LAB / FIELD MANUAL</div><h2>Welcome to Sector 04</h2><p class="modal-intro">A remote research outpost, one deep-core drill, and a whole lot of ground to cover. Keep the rig running and the lights on.</p><div class="guide-grid"><article class="guide-item"><b>01 · OPERATE THE RIG</b><p>Walk to the drill and press E or USE. Drilling consumes fuel, increases depth, and gradually wears down the rig.</p></article><article class="guide-item"><b>02 · KEEP IT SUPPLIED</b><p>Buy fuel at the Oil Depot. Funds arrive automatically every five seconds; recovered samples also earn a bonus.</p></article><article class="guide-item"><b>03 · RESEARCH</b><p>Upgrade speed, sample value, casing durability, and fuel recovery at the Research Lab.</p></article><article class="guide-item"><b>04 · NIGHT SHIFT</b><p>Time passes in the field. Power interruptions may draw something toward the yard—use cameras and keep moving.</p></article></div><p class="modal-intro" style="margin:18px 0 0"><b>CONTROLS</b> · WASD / arrows to move · mouse drag or VIEW to rotate · E / USE to interact · Esc to close</p>`)}
function formatTime(seconds){seconds=Math.max(0,Math.ceil(seconds));return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}
